def sunsetViews(heights):

    # Initialize a list to store the indices of buildings that can see the sunset
    sunset_indices = []

    # Start from the rightmost building and move left
    for i in range(len(heights) - 1, -1, -1):
        # Check if the current building is taller than all the buildings to its right
        if all(heights[i] >= heights[j] for j in range(i + 1, len(heights))):
            sunset_indices.append(i)

    # Return the list of indices in ascending order
    return sorted(sunset_indices)

