def balancedParenthesesAndSum(expression):
    stack = []
    for char in expression:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack or stack[-1] != '(':
                return -1
            stack.pop()
    if stack:
        return -1
    # Calculate sum of digits
    return sum(int(digit) for digit in expression if digit.isdigit())

# Test cases
print(balancedParenthesesAndSum("(1(2)3)") == 6)
print(balancedParenthesesAndSum("((1)23)") == 6)
print(balancedParenthesesAndSum(") (1(2)3") == -1)

