from typing import List

def min_completion_time(tasks: List[int]) -> int:
    tasks.sort()
    total_time = sum(tasks)
    left = 0
    right = len(tasks) - 1
    first_worker_time = 0
    second_worker_time = 0

    while left <= right:
        if first_worker_time + tasks[left] <= second_worker_time + tasks[left]:
            first_worker_time += tasks[left]
            left += 1
        else:
            second_worker_time += tasks[left]
            left += 1

    return max(first_worker_time, second_worker_time)

